#!/usr/bin/env python3
"""Assemble FINAL_REPORT.md from files on disk (git status/diff stat run live; outputs pasted verbatim)."""
import subprocess
from pathlib import Path
BASE = Path(__file__).resolve().parents[2]
F = BASE / "experiments/synth_kg_fix"
def sh(cmd): return subprocess.run(cmd, shell=True, capture_output=True, text=True, cwd=BASE).stdout.rstrip()
def rd(name): return (F / name).read_text(encoding="utf-8").rstrip()
def code(t): return "```\n" + t + "\n```\n"
parts = []
add = parts.append
add("# FINAL REPORT - synth_kg_fix\n\nGenerated by `experiments/synth_kg_fix/build_final_report.py` from files on disk. Sections 1, 5 and parts of 3-4 are pasted verbatim from script outputs. Nothing was committed.\n")
add("## 1. Repository state\n\n### git status\n" + code(sh("git status --short")) + "\n### git diff --stat\n" + code(sh("git diff --stat")) + "\nUntracked files that belong to the frozen directories (not shown by `git diff`): `tests/test_synth_kg_fixes.py`, `prompts/relationship_extraction_v1_1.txt`.\n\n### Test counts (`final_test_counts.txt`, run after the seed-11 evaluation)\n" + code(rd("final_test_counts.txt")) + "Baseline recorded at the start of this task: 195 passed, 0 skipped (the 1 skipped test of the 194/1 baseline is `test_live_ollama_embedding_service`, which runs when Ollama is reachable). After the fixes: 224 passed, 0 skipped (29 new tests in `tests/test_synth_kg_fixes.py`).\n")
add("## 2. Phase 0: prior claims (full text: `step0_reverify.txt`)\n\n" + code(rd("step0_reverify.txt").split("====================================================================================================\nB1.")[0].rstrip()))
add("## 3. Fixes (file:line, flags enabled)\n\n" + rd("CHECKPOINT_1.md").split("---\n# Addendum")[0].split("\n", 1)[1] + "\nFlags enabled in `configs/domains/company.yaml`: `person_like_types: [EMPLOYEE]`, `resolution.merge_exact_name_across_types`, `resolution.revalidate_relationships_after_resolution`, `resolution.enable_initial_surname_person_merge`. All three resolution flags are false in `configs/default.yaml`. The enabling was decided on dev data (seed 7). `relationship_extraction_version` stays at v1.0 (Phase 2c rule below).\n\n### Addendum: 55 vs 53 relationships\n" + rd("CHECKPOINT_1.md").split("---\n# Addendum")[1].split("\n", 1)[1])
add("## 4. Phase 2 tables (seed 7)\n\n### 2a/2b summary (`CHECKPOINT_2.md`)\n" + rd("CHECKPOINT_2.md").split("\n", 1)[1] + "\n### 2b full output (`phase2b_tables.txt`, pasted)\n" + code(rd("phase2b_tables.txt")) + "\n### 2c full output (`fix3_dev_test_output.txt`, pasted)\n" + code(rd("fix3_dev_test_output.txt")))
add("## 5. Phase 3 tables (seed 11)\n\n### Hashes\nBefore generation (`frozen_diff_sha.txt`):\n" + code(rd("frozen_diff_sha.txt")) + "\nAfter the final evaluation (`frozen_diff_sha_after.txt`):\n" + code(rd("frozen_diff_sha_after.txt")) + "\nBoth hashes are identical: no protocol violation.\n\n### Pre-registered evaluation (`seed11_eval_output.txt`, pasted)\n" + code(rd("seed11_eval_output.txt")) + "\n### Descriptive tables (`seed11_tables.txt`, pasted)\n" + code(rd("seed11_tables.txt")) + "\n### Checkpoint text\n" + rd("CHECKPOINT_3.md").split("\n", 1)[1])
add(rd("final_report_tail.md"))
(F / "FINAL_REPORT.md").write_text("\n".join(parts) + "\n", encoding="utf-8")
print("written", F / "FINAL_REPORT.md")
